Plan: Use the active sheet as the answer sheet. For each item in E6:E8, scan rows 2 through the last row of columns A/B, counting B when non-empty and falling back to A only when B is empty. Write the three counts into F6:F8 as plain integers.

```python
import shutil
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

ws = wb.active
vws = vals[ws.title]

def norm(value):
    if value is None:
        return ""
    return str(value).strip()

items = []
for row in range(6, 9):
    item = norm(vws.cell(row=row, column=5).value)
    items.append(item)

counts = []
for item in items:
    count = 0
    if item:
        for row in range(2, vws.max_row + 1):
            b_val = norm(vws.cell(row=row, column=2).value)
            a_val = norm(vws.cell(row=row, column=1).value)

            if b_val == "":
                if a_val == item:
                    count += 1
            else:
                if b_val == item:
                    count += 1
    counts.append(count)

for i, count in enumerate(counts):
    ws.cell(row=6 + i, column=6).value = count

wb.save(OUT)

print("items:", items)
print("counts:", counts)
